  'auth.ulangiPh': ['Ketik ulang kata sandi', 'Re-enter your password', 'Taip semula kata laluan', 'Ketik maneh tembung sandi', 'Ketik deui kecap sandi', '再次输入密码', 'もう一度入力'],
